const fs = require('fs');
const ROOT = '/skills';
const NAME_RE = /^[a-z0-9][a-z0-9-]{0,63}$/;
const MAX_BYTES = 64 * 1024;
const MAX_DESCRIPTION = 400;

// Chỉ nhận file SKILL.md thật (không symlink) nằm trực tiếp trong /skills/<tên>/ .
const inspect = (dirName) => {
  if (typeof dirName !== 'string' || !NAME_RE.test(dirName)) return null;
  try {
    const dirPath = ROOT + '/' + dirName;
    const dir = fs.lstatSync(dirPath);
    if (dir.isSymbolicLink() || !dir.isDirectory()) return null;
    const file = dirPath + '/SKILL.md';
    const st = fs.lstatSync(file);
    if (st.isSymbolicLink() || !st.isFile()) return null;
    if (fs.realpathSync(file) !== fs.realpathSync(ROOT) + '/' + dirName + '/SKILL.md') return null;
    return { name: dirName, file, size: st.size };
  } catch (e) {
    return null;
  }
};

// Frontmatter YAML đơn giản: name và description (một dòng, hoặc nhiều dòng dạng > / |).
const parseFrontmatter = (text) => {
  const source = String(text);
  const m = /^---[ \t]*\r?\n([\s\S]*?)\r?\n---[ \t]*(?:\r?\n|$)/.exec(source.charCodeAt(0) === 0xfeff ? source.slice(1) : source);
  if (!m) return null;
  const lines = m[1].split(/\r?\n/);
  const out = {};
  for (let i = 0; i < lines.length; i += 1) {
    const kv = /^([A-Za-z][A-Za-z0-9_-]*):[ \t]*(.*)$/.exec(lines[i]);
    if (!kv) continue;
    let value = kv[2].trim();
    if (/^[>|][+-]?$/.test(value)) {
      const parts = [];
      while (i + 1 < lines.length && (/^[ \t]+\S/.test(lines[i + 1]) || lines[i + 1].trim() === '')) {
        i += 1;
        parts.push(lines[i].trim());
      }
      value = parts.filter(Boolean).join(' ');
    } else if (value.length >= 2 && ((value[0] === '"' && value.endsWith('"')) || (value[0] === "'" && value.endsWith("'")))) {
      value = value.slice(1, -1);
    }
    out[kv[1]] = value.replace(/\s+/g, ' ').trim();
  }
  return out;
};

// Đọc và kiểm tra một skill: trả { name, description, content } hoặc null nếu không hợp lệ.
const readSkill = (entry) => {
  const content = fs.readFileSync(entry.file, 'utf8');
  const fm = parseFrontmatter(content);
  if (!fm || fm.name !== entry.name || !fm.description) return null;
  const chars = Array.from(fm.description);
  const description = chars.length > MAX_DESCRIPTION ? chars.slice(0, MAX_DESCRIPTION - 1).join('') + '…' : fm.description;
  return { name: entry.name, description, content };
};

// Danh sách skill hợp lệ đọc lúc chạy (allowlist động): skill nào lỗi hoặc quá lớn thì bỏ qua.
const listSkills = () => {
  let names = [];
  try {
    names = fs.readdirSync(ROOT).filter((n) => NAME_RE.test(n)).sort();
  } catch (e) {
    return [];
  }
  const skills = [];
  for (const dirName of names) {
    const entry = inspect(dirName);
    if (!entry || entry.size > MAX_BYTES) continue;
    try {
      const skill = readSkill(entry);
      if (skill) skills.push({ name: skill.name, description: skill.description });
    } catch (e) {
      // bỏ qua skill không đọc được
    }
  }
  return skills;
};
const skills = listSkills();
const skills_metadata = skills.length ? skills.map((s) => '- ' + s.name + ': ' + s.description).join('\n') : '(chưa có skill nào)';
return [{ json: { skills_metadata, skills } }];

